/// <summary>
///    AVA <c>Clicked</c> class.
/// </summary>
public void clicked()
{
    Args                locArgs;
    FormDataSource      locFormDataSource;
    InventTransferTable locInventTransferTable;

    locArgs                 = new Args();
    locFormDataSource       = element.InventTransferTable_DS;
    locInventTransferTable  = locFormDataSource.cursor();
    locArgs.caller(element);
    locArgs.record(locInventTransferTable);
    InventTransferTable::avaItemSetExpandPossiblePositions(locArgs, locInventTransferTable.TransferId);

    next clicked();

    locFormDataSource.research(true);
    locFormDataSource.refresh();
}
